// Set by main.ts from the Studio's language (the one chosen in Blup).
export let t = navigator.language.toLowerCase().startsWith("pt") ? pt : en;
export function setLanguage(lang: string) {
  t = lang === "pt" ? pt : en;
  document.documentElement.lang = lang;
}
